export function getJHMLAProfile(acNo: number): MLAProfile | undefined {
  return JH_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getJHMLAsByParty(party: string): MLAProfile[] {
  return JH_MLA_PROFILES.filter(p => p.party === party);
}

export function getJHFemaleMLAs(): MLAProfile[] {
  return JH_MLA_PROFILES.filter(p => p.gender === 'F');
}
